import React, { useState } from 'react';

const IncidentDetail = ({ incident, onClose, onStatusChange, onAddComment }) => {
  const [commentText, setCommentText] = useState('');
  const statusOptions = ['Open', 'In Progress', 'Closed'];

  if (!incident) return <div>Loading...</div>;

  const handleStatusChange = (e) => {
    onStatusChange(incident.id, e.target.value);
  };

  const handleAddComment = (e) => {
    e.preventDefault();
    if (!commentText) return;
    onAddComment(incident.id, commentText);
    setCommentText('');
  };

  return (
    <div>
      <button onClick={onClose}>Back to list</button>
      <h2>{incident.title}</h2>
      <p><strong>Description:</strong> {incident.description || '-'}</p>
      <p><strong>Severity:</strong> {incident.severity}</p>
      <p>
        <strong>Status:</strong>{' '}
        <select value={incident.status} onChange={handleStatusChange}>
          {statusOptions.map(s => (
            <option key={s} value={s}>{s}</option>
          ))}
        </select>
      </p>
      <p><strong>Assignee:</strong> {incident.assignee || '-'}</p>
      <p><strong>Created At:</strong> {new Date(incident.createdAt).toLocaleString()}</p>

      <h3>Comments</h3>
      <form onSubmit={handleAddComment}>
        <input
          value={commentText}
          onChange={e => setCommentText(e.target.value)}
          placeholder="Add comment"
        />
        <button type="submit">Add</button>
      </form>

      <ul>
        {incident.comments.map(c => (
          <li key={c.id}>
            {c.text} <small>({new Date(c.createdAt).toLocaleString()})</small>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default IncidentDetail;
